def unique_in_order(items):
    seen = set()
    result = []

    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)

    return result

print(unique_in_order([3, 1, 3, 2, 1, 4]))

from collections import Counter

def first_unique(text):
    counts = Counter(text)
    return next((char for char in text if counts[char] == 1), None)

print(first_unique("swiss"))
print(first_unique("aabb"))

from functools import wraps

def retry(exception_type, attempts=3):
    def decorate(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exception_type:
                    if attempt == attempts:
                        raise
        return wrapper
    return decorate

calls = 0

@retry(TimeoutError, attempts=3)
def flaky():
    global calls
    calls += 1
    if calls < 3:
        raise TimeoutError("temporary")
    return "ok"

print(flaky())
print(calls)

def chunks(items, size):
    if size <= 0:
        raise ValueError("size must be positive")

    for start in range(0, len(items), size):
        yield items[start:start + size]

print(list(chunks([1, 2, 3, 4, 5], 2)))

class ConfigError(RuntimeError):
    pass

def read_required(config, key):
    try:
        return config[key]
    except KeyError as exc:
        raise ConfigError(f"Missing required key: {key}") from exc

try:
    read_required({}, "token")
except ConfigError as exc:
    print(type(exc.__cause__).__name__)
    print(exc)

